function updateHud(){const ps=clamp(player.stamina,0,100),es=clamp(enemy.stamina,0,100);$('playerStaminaBar').style.width=ps+'%';$('enemyStaminaBar').style.width=es+'%';$('playerStaminaText').textContent=Math.ceil(ps)+'%';$('enemyStaminaText').textContent=Math.ceil(es)+'%';$('playerSpin').textContent=Math.round(player.spin);$('enemySpin').textContent=Math.round(enemy.spin);$('boostBar').style.width=boost+'%';$('boostText').textContent=Math.floor(boost)+'%';$('roundNumber').textContent=String(round).padStart(2,'0')}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.035);updatePhysics(dt);
  for(const b of [player,enemy]){
    b.blade.rotation.y-=dt*(b.spin/60)*.095;
    const wobble=b.wobble*(.13+Math.sin(clock.elapsedTime*24)*.045);b.blade.rotation.x=Math.sin(clock.elapsedTime*18+(b.isPlayer?0:1))*wobble;b.blade.rotation.z=Math.cos(clock.elapsedTime*17+(b.isPlayer?1:0))*wobble;
    b.group.position.y=Math.abs(Math.sin(clock.elapsedTime*9+(b.isPlayer?0:1)))*.035;
    b.glow.intensity=Math.max(b.hitFlash*12,b.spin/1500);b.hitFlash=Math.max(0,b.hitFlash-dt);
  }
  for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.x+=p.vx*dt;p.mesh.position.y+=p.vy*dt;p.mesh.position.z+=p.vz*dt;p.vy-=5*dt;p.mesh.material.opacity=clamp(p.life*1.8,0,1);if(p.life<=0){scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();particles.splice(i,1)}}
  if(charging){charge=clamp((performance.now()-chargeStart)/1700,0,1);$('launchBtn').style.setProperty('--charge',(charge*100)+'%');$('chargeValue').textContent=Math.round(charge*100)+'%';$('chargeReadout').classList.add('show')}
  updateHud();renderer.render(scene,camera);
}
function beginCharge(e){if(state==='over'){resetRound();return}if(state!=='ready')return;e.preventDefault();charging=true;chargeStart=performance.now();$('launchBtn').classList.add('charging');try{$('launchBtn').setPointerCapture(e.pointerId)}catch{}}
function releaseCharge(e){if(!charging)return;e?.preventDefault();charging=false;$('launchBtn').classList.remove('charging');$('chargeReadout').classList.remove('show');$('launchBtn').style.setProperty('--charge','0%');const power=Math.max(.16,charge);charge=0;launch(power)}
function resetRound(){clearTimeout(toastTimer);$('toast').className='toast';state='ready';charge=0;charging=false;boost=100;boostHeld=false;$('launchBtn').disabled=false;$('launchBtn').classList.remove('charging');$('launchLabel').textContent='HOLD TO CHARGE';$('launchSub').textContent='RELEASE TO LAUNCH';$('battleStatus').textContent='READY TO LAUNCH';player.glow.intensity=enemy.glow.intensity=0;placeReady()}
$('launchBtn').addEventListener('pointerdown',beginCharge);$('launchBtn').addEventListener('pointerup',releaseCharge);$('launchBtn').addEventListener('pointercancel',releaseCharge);$('launchBtn').addEventListener('contextmenu',e=>e.preventDefault());
$('resetBtn').addEventListener('click',()=>{if(state==='battle'||state==='countdown')round=Math.max(1,round);resetRound()});
$('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('soundBtn').style.color=soundOn?'var(--cyan)':'#a8bed0';$('soundBtn').textContent=soundOn?'♫':'♪';if(soundOn)playTone(540,.08)});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;keys[e.key]=true;if([' ','arrowleft','arrowright','arrowup'].includes(k))e.preventDefault();if(k===' '||k==='w'){if(!boostHeld){boostHeld=true;attackBoost()}}});
window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys[k]=false;keys[e.key]=false;if(k===' '||k==='w')boostHeld=false});
// Simple touch steering on the arena: left/right halves steer, double-tap boosts.
let lastTouch=0;renderer?.domElement?.addEventListener('touchstart',e=>{if(e.target.closest('button'))return;const now=performance.now();if(now-lastTouch<320)attackBoost();lastTouch=now;keys[e.touches[0].clientX<innerWidth/2?'a':'d']=true},{passive:true});renderer?.domElement?.addEventListener('touchend',()=>{keys.a=keys.d=false},{passive:true});
init();
</script>
</body>
